const pageRepositoryTransfers = `-- name: PageRepositoryTransfers :many
SELECT transfer.id, transfer.repository_id, transfer.source_owner_did, transfer.source_organization_id, transfer.source_owner_alias, transfer.source_repository_uri, transfer.source_repository_cid, transfer.destination_owner_did, transfer.destination_organization_id, transfer.destination_owner_alias, transfer.initiated_by_did, transfer.accepted_by_did, transfer.proposal_uri, transfer.proposal_cid, transfer.successor_uri, transfer.successor_cid, transfer.acceptance_uri, transfer.acceptance_cid, transfer.source_redirect_cid, transfer.status, transfer.created_at, transfer.expires_at, transfer.acceptance_started_at, transfer.accepted_at, transfer.cancelled_at
FROM core.repository_transfers AS transfer
WHERE transfer.repository_id = $1
  AND (
    $2::uuid IS NULL
    OR (transfer.created_at, transfer.id) < (
      SELECT cursor.created_at, cursor.id
      FROM core.repository_transfers AS cursor
      WHERE cursor.repository_id = $1
        AND cursor.id = $2::uuid
    )
  )
ORDER BY transfer.created_at DESC, transfer.id DESC
LIMIT $3
`

type PageRepositoryTransfersParams struct {
	RepositoryID pgtype.UUID `json:"repository_id"`
	AfterID      pgtype.UUID `json:"after_id"`
	PageLimit    int32       `json:"page_limit"`
}

func (q *Queries) PageRepositoryTransfers(ctx context.Context, arg PageRepositoryTransfersParams) ([]CoreRepositoryTransfer, error) {
	rows, err := q.db.Query(ctx, pageRepositoryTransfers, arg.RepositoryID, arg.AfterID, arg.PageLimit)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []CoreRepositoryTransfer{}
	for rows.Next() {
		var i CoreRepositoryTransfer
		if err := rows.Scan(
			&i.ID,
			&i.RepositoryID,
			&i.SourceOwnerDid,
			&i.SourceOrganizationID,
			&i.SourceOwnerAlias,
			&i.SourceRepositoryUri,
			&i.SourceRepositoryCid,
			&i.DestinationOwnerDid,
			&i.DestinationOrganizationID,
			&i.DestinationOwnerAlias,
			&i.InitiatedByDid,
			&i.AcceptedByDid,
			&i.ProposalUri,
			&i.ProposalCid,
			&i.SuccessorUri,
			&i.SuccessorCid,
			&i.AcceptanceUri,
			&i.AcceptanceCid,
			&i.SourceRedirectCid,
			&i.Status,
			&i.CreatedAt,
			&i.ExpiresAt,
			&i.AcceptanceStartedAt,
			&i.AcceptedAt,
			&i.CancelledAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const resolveRepositoryTransferOwner = `-- name: ResolveRepositoryTransferOwner :one
SELECT route.alias, route.kind, route.account_did, route.organization_id,
       organization.creator_did, organization.at_uri AS organization_uri,
       organization.at_cid AS organization_cid
FROM core.owner_routes AS route
LEFT JOIN core.organizations AS organization
  ON organization.id = route.organization_id
 AND organization.state = 'active'
 AND organization.deleted_at IS NULL
WHERE lower(route.alias) = lower($1)
   OR (route.kind = 'account' AND route.account_did = $1)
ORDER BY CASE WHEN lower(route.alias) = lower($1) THEN 0 ELSE 1 END, route.created_at DESC
LIMIT 1
`

type ResolveRepositoryTransferOwnerRow struct {
	Alias           string      `json:"alias"`
	Kind            string      `json:"kind"`
	AccountDid      pgtype.Text `json:"account_did"`
	OrganizationID  pgtype.UUID `json:"organization_id"`
	CreatorDid      pgtype.Text `json:"creator_did"`
	OrganizationUri pgtype.Text `json:"organization_uri"`
	OrganizationCid pgtype.Text `json:"organization_cid"`
}

func (q *Queries) ResolveRepositoryTransferOwner(ctx context.Context, owner string) (ResolveRepositoryTransferOwnerRow, error) {
	row := q.db.QueryRow(ctx, resolveRepositoryTransferOwner, owner)
	var i ResolveRepositoryTransferOwnerRow
	err := row.Scan(
		&i.Alias,
		&i.Kind,
		&i.AccountDid,
		&i.OrganizationID,
		&i.CreatorDid,
		&i.OrganizationUri,
		&i.OrganizationCid,
	)
	return i, err
}

const resolveRepositoryTransferSourceAlias = `-- name: ResolveRepositoryTransferSourceAlias :one
SELECT route.alias
FROM core.repositories AS repository
JOIN core.owner_routes AS route ON (
  (repository.organization_id IS NULL AND route.kind = 'account' AND route.account_did = repository.owner_did)
  OR (repository.organization_id IS NOT NULL AND route.kind = 'organization' AND route.organization_id = repository.organization_id)
)
WHERE repository.id = $1
  AND repository.state = 'active'
  AND repository.deleted_at IS NULL
LIMIT 1
`

func (q *Queries) ResolveRepositoryTransferSourceAlias(ctx context.Context, repositoryID pgtype.UUID) (string, error) {
	row := q.db.QueryRow(ctx, resolveRepositoryTransferSourceAlias, repositoryID)
	var alias string
	err := row.Scan(&alias)
	return alias, err
}

